<?php
/**
 * Development OTP provider — never sends SMS.
 *
 * @package ThreeBest\Core
 */

declare( strict_types = 1 );

namespace ThreeBest\Core\Otp;

defined( 'ABSPATH' ) || exit;

/**
 * A stand-in that lets the verification flow be exercised without Twilio.
 *
 * It sends nothing. The code is generated by Otp_Service, hashed into our own
 * table, and written to the PHP error log so a developer can read it back.
 *
 * ---------------------------------------------------------------------------
 * WHY THIS CANNOT LEAK INTO PRODUCTION
 * ---------------------------------------------------------------------------
 * A development verifier that accepts a code nobody had to receive is, by
 * definition, a way to submit leads with an unowned phone number. So it is
 * gated on an explicit opt-in that nobody sets by accident:
 *
 *     define( 'THREEBEST_ALLOW_DEV_OTP', true );   // wp-config.php
 *
 * Without that constant is_available() returns false, the factory refuses to
 * select it, and the flow falls back to the real provider. WP_DEBUG was
 * considered and rejected as the gate: it is routinely left on by accident,
 * and it does not express intent about phone verification.
 *
 * sends_sms() returns false, so every caller — the lead flow, the logs and the
 * admin screen — can tell a development "verification" from a real one.
 *
 * The fixed demo code from the React prototype (123456) is deliberately NOT
 * reproduced. Codes here are cryptographically random, so the development flow
 * exercises the same path a real one does rather than a shortcut.
 */
final class Dev_Otp_Provider implements Otp_Provider {

	/**
	 * {@inheritDoc}
	 */
	public function name(): string {
		return 'dev';
	}

	/**
	 * {@inheritDoc}
	 */
	public function is_available(): bool {
		if ( ! defined( 'THREEBEST_ALLOW_DEV_OTP' ) || ! THREEBEST_ALLOW_DEV_OTP ) {
			return false;
		}

		/*
		 * SECOND GATE, ADDED IN PHASE 9.
		 *
		 * The constant alone was one mistake away from being a disaster: copy a
		 * development wp-config.php to production, or restore a database whose
		 * options row still says otp_provider = 'dev', and verification would
		 * accept a code nobody had to receive.
		 *
		 * wp_get_environment_type() is WordPress's own answer to "where am I",
		 * it defaults to 'production' when nothing says otherwise, and it is
		 * set by WP_ENVIRONMENT_TYPE — a different switch in a different place
		 * from the constant above. Both must agree before this provider can be
		 * selected, and the safe answer is the default one.
		 */
		return 'production' !== wp_get_environment_type();
	}

	/**
	 * {@inheritDoc}
	 *
	 * False, always. Nothing is delivered.
	 */
	public function sends_sms(): bool {
		return false;
	}

	/**
	 * "Sends" a code by writing it to the error log.
	 *
	 * This is the one place in the plugin that deliberately writes a
	 * verification code anywhere. It is reachable only behind the explicit
	 * opt-in above, and the line is marked so it is obvious in a log.
	 *
	 * @param string $phone_e164 Number in E.164 form.
	 * @param string $code       The code Otp_Service generated.
	 */
	public function request( string $phone_e164, string $code = '' ): Otp_Result {
		if ( ! $this->is_available() ) {
			return Otp_Result::failure( $this->name(), Otp_Result::FAILED, array( 'stage' => 'not_enabled' ) );
		}

		if ( '' === $code ) {
			return Otp_Result::failure( $this->name(), Otp_Result::FAILED, array( 'stage' => 'no_code_supplied' ) );
		}

		// Last four digits only: enough to tell two test numbers apart without
		// writing a full phone number into a log file.
		// phpcs:ignore WordPress.PHP.DevelopmentFunctions.error_log_error_log
		error_log(
			sprintf(
				'[3Best][DEV OTP] NO SMS SENT. Verification code for ...%s is %s',
				substr( $phone_e164, -4 ),
				$code
			)
		);

		return Otp_Result::sent( $this->name(), 'dev-' . substr( hash( 'sha256', $phone_e164 ), 0, 12 ) );
	}

	/**
	 * {@inheritDoc}
	 *
	 * Checking happens in Otp_Service against the stored hash, because this
	 * provider holds no state of its own. Reaching "verified" here only means
	 * the provider had no objection.
	 *
	 * @param string $phone_e164 Number in E.164 form.
	 * @param string $code       The code the user entered.
	 */
	public function verify( string $phone_e164, string $code ): Otp_Result {
		unset( $phone_e164, $code );

		if ( ! $this->is_available() ) {
			return Otp_Result::failure( $this->name(), Otp_Result::FAILED, array( 'stage' => 'not_enabled' ) );
		}

		return Otp_Result::verified( $this->name() );
	}
}
